// Each record with a Nested field still derives its protocol schema (the
// wrapper is a binary column).
func TestNestedBinarySchemas(t *testing.T) {
	for _, tc := range []struct {
		name   string
		value  any
		schema *arrow.Schema
	}{
		{"BindRequest", generated.BindRequest{}, generated.BindRequestSchema},
		{"ArgumentsLocation", generated.ArgumentsLocation{}, generated.ArgumentsLocationSchema},
		{"InitRequest", generated.InitRequest{}, generated.InitRequestSchema},
		{"TableFunctionCardinalityRequest", generated.TableFunctionCardinalityRequest{}, generated.TableFunctionCardinalityRequestSchema},
		{"TableFunctionStatisticsRequest", generated.TableFunctionStatisticsRequest{}, generated.TableFunctionStatisticsRequestSchema},
		{"TableFunctionDynamicToStringRequest", generated.TableFunctionDynamicToStringRequest{}, generated.TableFunctionDynamicToStringRequestSchema},
		{"TableFunctionPlanRequest", generated.TableFunctionPlanRequest{}, generated.TableFunctionPlanRequestSchema},
		{"TableFunctionProjectionRequest", generated.TableFunctionProjectionRequest{}, generated.TableFunctionProjectionRequestSchema},
	} {
		got, err := vgirpc.SchemaForStruct(reflect.TypeOf(tc.value))
		if err != nil {
			t.Fatalf("deriving %s: %v", tc.name, err)
		}
		if !got.Equal(tc.schema) {
			t.Fatalf("%s derives\n%v\nbut the protocol declares\n%v", tc.name, got, tc.schema)
		}
	}
}

