func TestNestedBinaryTypedConstruction(t *testing.T) {
	args := []byte("arguments-ipc")
	path := []string{"main", "typed"}
	bind := generated.BindRequest{
		FunctionName: "typed_construction",
		Arguments:    &args,
		FunctionType: "TABLE",
		SchemaPath:   &path,
	}
	wrapped, err := generated.NestedOf(bind)
	if err != nil {
		t.Fatal(err)
	}
	schema := []byte("output-schema-ipc")
	init := generated.InitRequest{BindCall: wrapped, OutputSchema: schema}
	first, err := vgirpc.MarshalRecord(init)
	if err != nil {
		t.Fatal(err)
	}
	second, err := vgirpc.MarshalRecord(init)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(first, second) || !bytes.Equal(nestedColumn(t, first, "bind_call"), wrapped.Bytes()) {
		t.Fatal("encoding the same wrapper twice must give identical bytes, equal to the held ones")
	}
	var back generated.InitRequest
	if err := vgirpc.UnmarshalRecord(first, &back); err != nil {
		t.Fatal(err)
	}
	got, err := back.BindCallValue()
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got, bind) {
		t.Fatalf("typed round trip gave %+v, want %+v", got, bind)
	}
	if !back.BindCall.Equal(wrapped) {
		t.Fatal("a decoded wrapper must equal the one encoded, by bytes")
	}
}

func TestNestedBinaryWrapperContract(t *testing.T) {
	var zero generated.Nested[generated.BindRequest]
	if _, err := zero.Get(); err == nil {
		t.Fatal("the zero wrapper must fail at access")
	}
	if _, err := vgirpc.MarshalRecord(generated.InitRequest{OutputSchema: []byte{1}}); err == nil {
		t.Fatal("encoding a zero wrapper must fail, not write empty bytes")
	}
	if _, err := generated.NestedFromBytes[generated.BindRequest](nil).Get(); err == nil {
		t.Fatal("a non-null wrapper over zero bytes must fail at access")
	}
	// A malformed nested value does not fail the embedding decode; it fails at
	// access, naming the field path.
	bad := generated.InitRequest{
		BindCall:     generated.NestedFromBytes[generated.BindRequest]([]byte("not an IPC stream")),
		OutputSchema: []byte{1},
	}
	encoded, err := vgirpc.MarshalRecord(bad)
	if err != nil {
		t.Fatal(err)
	}
	var back generated.InitRequest
	if err := vgirpc.UnmarshalRecord(encoded, &back); err != nil {
		t.Fatalf("a malformed nested value must not fail the embedding decode: %v", err)
	}
	if _, err := back.BindCallValue(); err == nil || !strings.HasPrefix(err.Error(), "InitRequest.bind_call: ") {
		t.Fatalf("access error %v must name InitRequest.bind_call", err)
	}
	// The held bytes are a private copy: changing the source or Bytes() result
	// cannot change them.
	source := nestedFile(t, "bind_call.bin")
	wrapped := generated.NestedFromBytes[generated.BindRequest](source)
	source[0] ^= 0xff
	wrapped.Bytes()[1] ^= 0xff
	if !bytes.Equal(wrapped.Bytes(), nestedFile(t, "bind_call.bin")) {
		t.Fatal("the held bytes changed")
	}
	if s := wrapped.String(); !strings.Contains(s, "bytes") {
		t.Fatalf("String() = %q", s)
	}
}

func TestNestedBinaryConcurrentFirstAccess(t *testing.T) {
	wrapped := generated.NestedFromBytes[generated.BindRequest](nestedFile(t, "bind_call.bin"))
	results := make(chan string, 16)
	for range 16 {
		go func() {
			v, err := wrapped.Get()
			if err != nil {
				results <- err.Error()
				return
			}
			results <- v.FunctionName
		}()
	}
	for range 16 {
		if got := <-results; got != "nested_binary_fixture" {
			t.Fatalf("concurrent first access gave %q", got)
		}
	}
}

func TestNestedBinaryNullArguments(t *testing.T) {
	m := nestedLoadManifest(t)
	if len(m.Binds) == 0 {
		t.Fatal("manifest lists no bind fixtures")
	}
	for _, b := range m.Binds {
		t.Run(b.File, func(t *testing.T) {
			var r generated.BindRequest
			if err := vgirpc.UnmarshalRecord(nestedFile(t, b.File), &r); err != nil {
				t.Fatal(err)
			}
			exactlyOne := (r.Arguments == nil) != (r.ArgumentsLocation == nil)
			if exactlyOne != b.Valid {
				t.Fatalf("exactly-one check = %v, want valid=%v (%s)", exactlyOne, b.Valid, b.ErrorKind)
			}
			if b.ArgumentsLocation == nil {
				return
			}
			// Go's []byte would accept a nil silently: assert it explicitly.
			if r.Arguments != nil {
				t.Fatalf("arguments decoded as %d bytes, want null", len(*r.Arguments))
			}
			l := r.ArgumentsLocation
			if l == nil || hex.EncodeToString(l.Ref) != b.ArgumentsLocation.Ref.Hex ||
				l.Size != b.ArgumentsLocation.Size || l.Sha256 != b.ArgumentsLocation.Sha256 {
				t.Fatalf("arguments_location = %+v, want %+v", l, b.ArgumentsLocation)
			}
		})
	}
}
